UPDATE public.courses SET description='충주 풍경길 종댕이길의 두루누비 공식 GPX 전체 140개 좌표를 표시합니다. 표시 좌표로 계산한 거리는 약 6.84km이며 공식 안내 전체 거리는 7.5km입니다. 한국관광공사 종댕이길 안내에서 전구역·전 견종 동반 가능, 목줄 착용, 배변봉투 지참·배변 처리와 맹견 입마개 조건을 확인했습니다. 실내 시설 출입 허용을 뜻하지 않습니다. 계단·경사·쉼터·반려견 보행 난이도와 현재 통제는 미확인으로 현장 안내를 확인하세요. 출발·도착은 GPX 좌표이며 정문·주차장 위치로 확인한 것이 아닙니다. 사진은 종댕이길의 실제 경관 참고자료이며 전체 경로 또는 현재 상태를 보장하지 않습니다. 동반안내: https://api.visitkorea.or.kr/#/hubTourSearchCatDetail?contentId=2043017&langDiv=KOR 공식안내: https://www.durunubi.kr/course-detail-view.do?crs_idx=T_CRS_MNG0000004071 확인일: 2026-10-17',diff='미확인',distance='약 6.84km',tags=ARRAY['충북','공식안내','목줄필수','공식GPX'],status='approved' WHERE id='duru_T_CRS_MNG0000004071' AND status='pending' AND name='충북 충주시 충주풍경길 종댕이길' AND md5(path::text)='0e233886baa6fd8a46d52d1e48e1c41d' RETURNING id,name,status;
